    id: "gs-athlete-heat-acclimation",
    goal: "athlete", tier: "advanced", section: "9410",
    title: "Heat-Acclimate for 10–14 Days Before Hot Competitions",
    subtitle: "Repeated exercise-heat exposure lowers strain and raises performance in the heat and, in one trial, in the cool",
